      "id": 1,
      "claim": "Einstein’s photoelectric equation is K_max = hν – φ",
      "evidence": "Einstein’s theory relates the maximum kinetic energy of emitted electrons to the photon energy (hν) minus the metal’s work function (φ).",
      "weight": 0.6,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping potential V_stop satisfies e·V_stop = K_max",
      "evidence": "By definition, the stopping potential is the voltage needed to reduce the photocurrent to zero, i.e., to cancel the kinetic energy of the most energetic electrons.",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Therefore V_stop = (h/e)·ν – φ/e, a linear function of the frequency ν",
      "evidence": "Substituting K_max from step 1 into step 2 and solving for V_stop gives a straight‑line relationship with slope h/e and intercept –φ/e.",
      "weight": 0.2,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The linear relationship holds only for frequencies above the threshold ν₀ = φ/h",
      "evidence": "Below ν₀ the photon energy is insufficient to overcome the work function, so no electrons are emitted and the equation does not apply.",
      "weight": 0.1,
      "depends_on": [1]
    },
    {
      "id": 5,
      "claim": "Option D states exactly this linear dependence of stopping potential on frequency above the threshold",
      "evidence": "Option D: “potential difference necessary to stop the emitted electrons is a linear function of the frequency above the threshold frequency.”",
      "weight": 0.9,
      "depends_on": [3, 4]
    }
  ],
